      id = "2921",
      title = "Ranger Epic 1.5:  Heartwood Blade",
      exp = "08",
      exp_name = "Omens of War",
      min_lvl = 70,
      max_lvl = 125,
      quest_type = "Quest",
      repeatable = true,
      group_size = "Raid",
      npc = "player",
      loc = { y = -3600.0, x = -1600.0, z = 0.0 },
      triggers = {
        "Hail, Althele",
        "What is out of balance?",
        "What diseases of the mind?",
        "You are diseased.",
        "Hail, Grinbik the Fertile",
        "Hail, Senvial of the Mist",
        "Hail, Uisima Lord of the Depths",
        "out of balance",
      },
      items_required = {
        { name = "it to Althele", count = 1 },
        { name = "the tuft to Corun Finisc in Surefall Glades", count = 1 },
        { name = "up the search", count = 1 },
        { name = "her Corun's Notes", count = 1 },
