      rewards = {
        { id = 35136, name = "Dawnseeker's Boots of the Defender", type = "item" },
        { id = 35472, name = "Dawnseeker's Chestpiece of the Defender", type = "item" },
        { id = 34892, name = "Dawnseeker's Coif of the Defender", type = "item" },
        { id = 35137, name = "Dawnseeker's Leggings of the Defender", type = "item" },
        { id = 35138, name = "Dawnseeker's Mitts of the Defender", type = "item" },
        { id = 32940, name = "Dawnseeker's Sleeves of the Defender", type = "item" },
