        { id = 32167, name = "Eye of the Lightninglord", type = "item" },
        { id = 30539, name = "Glowing Muramite Rune", type = "item" },
        { id = 30538, name = "Greater Muramite Rune", type = "item" },
        { id = 31731, name = "Horn of Doomcalling", type = "item" },
