      },
      items_required = {
        { name = "the Tokens to the Head Librarian 0/1 (Skylance", count = 1 },
      },
      rewards = {
        { id = 48507, name = "Clasp of the Fledgling Scrykin", type = "item" },
        { id = 48987, name = "Eye of Ice", type = "item" },
        { id = 50506, name = "Invisible Man Spirit Dust", type = "item" },
        { id = 47023, name = "Mantle of the Spirit Warrior", type = "item" },
