      },
      rewards = {
        { id = 50509, name = "Black Shard of Mana", type = "item" },
        { id = 48970, name = "Burning Tree Leaf", type = "item" },
        { id = 48971, name = "Cape of Cremation", type = "item" },
        { id = 48972, name = "Charred Darkwood Bow", type = "item" },
