      },
      rewards = {
        { id = 25932, name = "Chainmail of the Training Arena", type = "item" },
        { id = 25076, name = "Cherished Companion Shard", type = "item" },
        { id = 25074, name = "Dokorel's Renewal Stone", type = "item" },
