      repeatable = true,
      group_size = "Solo",
      npc = "player",
      loc = { y = 123.0, x = 740.0, z = 53.0 },
      triggers = {
        "Hail, Gihbra Artinguard",
        "Further?",
        "I",
        "Hail, Interix Tanglefuze",
        "I have questions for you...",
        "Turning their crank?",
