      loc = { y = 1135.0, x = 710.0, z = 138.0 },
      triggers = {
        "Hail, a glittering portal",
        "Prisoner?",
        "An unwilling witness?",
        "What life?",
        "How can I help?",
        "prisoner",
        "unwilling",
