        { id = 101245, name = "Azure Stud of the Breeze", type = "item" },
        { id = 101367, name = "Burning Belt of Endless Shadow", type = "item" },
        { id = 100418, name = "Eltarki's Diary - Four Cornered", type = "item" },
        { id = 99752, name = "Glowing Alaran Cantrip", type = "item" },
