      rewards = {
        { id = 15400, name = "Aggression", type = "item" },
        { id = 11797, name = "Armband of Serenity", type = "item" },
        { id = 8054, name = "Axe of the Warmaster", type = "item" },
        { id = 9002, name = "Bone Bladed Scimitar", type = "item" },
