      quest_type = "Quest",
      repeatable = true,
      group_size = "Solo",
      npc = "player",
      loc = { y = -220.0, x = -175.0, z = 0.0 },
      triggers = {
        "Hail, Merchant Ahlam",
        "I am interested in helping.",
        "How do you purify water?",
        "Hail, Gamali",
        "What is Gravel leaf tea?",
        "Hail, Guard Jabbar",
        "What Hollow palm tea [item=36570]?",
        "Hail, Legionnaire Neville",
      },
      items_required = {
        { name = "to Merchant Ahlam", count = 1 },
        { name = "her", count = 1 },
        { name = "Merchant Ahlam 4 x Crystal clear water", count = 1 },
