      rewards = {
        { id = 15795, name = "Acrylia Needle", type = "item" },
        { id = 15796, name = "Acrylia Thimble and Needle Set", type = "item" },
        { id = 9006, name = "Sleek Sonic Wolf Hide Jerkin", type = "item" },
