      loc = { y = -176.79, x = 52.26, z = -188.25 },
      triggers = {
        "Hail, Historian Sharar",
        "Yes",
        "What are the Khati Sha troubled by?",
        "The Khati Sha are disturbed about the spiritual realm",
        "Hail, Scout Vyrak",
