      repeatable = true,
      group_size = "Solo",
      npc = "player",
      loc = { y = 830.0, x = -600.0, z = 0.0 },
      triggers = {
        "Hail, Torsten Reidan",
        "What old friend?",
        "Where is Bregun Dorey?",
        "What supplies?",
        "Hail Bregun Dorey",
        "Trog",
        "I am from Norrath",
