      rewards = {
        { id = 15384, name = "Yttrium Dagger", type = "item" },
        { id = 20308, name = "Yttrium Falchion", type = "item" },
        { id = 20309, name = "Yttrium Long Sword", type = "item" },
        { id = 16181, name = "Yttrium Mace", type = "item" },
