      loc = { y = -1262.0, x = -1411.0, z = 28.0 },
      triggers = {
        "Hail, Veltar",
        "Tell me about the tynnonium shackle",
        "What are the three virtues?",
        "What is the trial of agility?",
        "What is the trial of patience?",
