      },
      rewards = {
        { id = 22933, name = "Custom Champion's Crown", type = "item" },
        { id = 25425, name = "Custom Cowl of Mortality", type = "item" },
        { id = 25428, name = "Custom Crown of Forbidden Rites", type = "item" },
        { id = 25439, name = "Custom Crown of the Kromzek Kings", type = "item" },
