      rewards = {
        { id = 7107, name = "Beer Goggles", type = "item" },
        { id = 3760, name = "Black Marble", type = "item" },
        { id = 6006, name = "Blue Resistance Stone", type = "item" },
        { id = 27540, name = "Club Sandwich", type = "item" },
