      title = "Berserker Epic 1.5 Pre-Quest",
      exp = "01",
      exp_name = "The Ruins of Kunark",
      min_lvl = 65,
      max_lvl = 125,
      quest_type = "Quest",
      repeatable = true,
      group_size = "Solo",
      npc = "player",
      loc = { y = -9.3, x = -61.69, z = 6.23 },
      triggers = {
        "Hail, Julei Direaxe",
        "I am here to learn how to wake the spirit of rage.",
        "What long-standing enemy?",
        "Hail, Kizrak the Tyrant",
