      loc = { y = 115.0, x = 995.0, z = 96.0 },
      triggers = {
        "Hail, Bantil Io`Tuv",
        "Another way?",
        "Footsteps?",
        "What is the source of his research?",
        "Great Library?",
        "Pieces?",
        "another way",
