      id = "4204",
      title = "Stirring Things Up",
      exp = "01",
      exp_name = "The Ruins of Kunark",
      min_lvl = 53,
      max_lvl = 53,
      quest_type = "Task",
      repeatable = false,
      group_size = "Solo",
      npc = "player",
      loc = nil,
      triggers = {
