      id = "4626",
      title = "Raiding the Drolvargs",
      exp = "01",
      exp_name = "The Ruins of Kunark",
      min_lvl = 50,
      max_lvl = 53,
      quest_type = "Task",
      repeatable = true,
      group_size = "Solo",
