      },
      items_required = {
      },
      rewards = {
        { id = 61547, name = "Band of Mortality", type = "item" },
        { id = 60678, name = "Blood Talon Necklace", type = "item" },
        { id = 61381, name = "Bloody Vampiric Cloak", type = "item" },
        { id = 45441, name = "Bristlebane's Ticket of Admission", type = "item" },
        { id = 62090, name = "Earring of Ghostly Chants", type = "item" },
        { id = 63450, name = "Earring of Spectral Essence", type = "item" },
