      },
      rewards = {
        { id = 63001, name = "Bone-Studded Cloak", type = "item" },
        { id = 45441, name = "Bristlebane's Ticket of Admission", type = "item" },
        { id = 62023, name = "Carved Bone Totem", type = "item" },
