      id = "654",
      title = "Medallion of the Kylong",
      exp = "01",
      exp_name = "The Ruins of Kunark",
      min_lvl = 45,
      max_lvl = 125,
      quest_type = "Quest",
      repeatable = true,
      group_size = "Solo",
