    {
      id = "803",
      title = "Trooper Scale Helm",
      exp = "01",
      exp_name = "The Ruins of Kunark",
      min_lvl = 25,
      max_lvl = 125,
      quest_type = "Quest",
      repeatable = true,
      group_size = "Solo",
      npc = "player",
      loc = nil,
      triggers = {
